#include <Arduino.h>
#include <Wire.h>
#include <SoftwareSerial.h>
#include <math.h>
#include <Servo.h>

// --- Пины ---
const int PIN_STEP = 2;
const int PIN_DIR  = 3;
const int PIN_ESC  = 9;
const int PIN_LIMIT = 4;

const int PIN_GPS_RX = 10;
const int PIN_GPS_TX = 11;

const int PIN_HOLD_BTN = 5;
const int PIN_EMER_BTN = 6;

// Адреса I2C
const uint8_t ADDR_ADXL345 = 0x53;
const uint8_t ADDR_HMC5883 = 0x1E;

// Регистры ADXL345
const uint8_t REG_POWER_CTL = 0x2D;
const uint8_t REG_DATA_FORMAT = 0x31;
const uint8_t REG_DATAX0 = 0x32;

// Регистры HMC5883L
const uint8_t REG_CONFIG_A = 0x00;
const uint8_t REG_MODE = 0x02;
const uint8_t REG_OUT_X_H = 0x03;

// Целевая точка — устанавливается по первому валидному GPS
float TARGET_LAT = 0.0;
float TARGET_LON = 0.0;
bool targetSet = false;
const float HOLD_RADIUS = 3.0; // метров

// Настройки механики
const unsigned long STEP_DELAY_US = 600;
const uint8_t BYTES_TO_READ = 6;
const uint8_t STOP_FLAG = 1;
const unsigned long CALIB_DELAY_US = 1200;
const float DEG_PER_STEP = 1.8;
const float MAX_RUDDER_ANGLE = 45.0;

// ESC (Servo)
Servo escServo;
const int PWM_NEUTRAL = 1500;
const int PWM_FWD = 2000;
const int PWM_REV = 1000;

// Переменные состояния
float currentRudderDeg = 0.0;
float stepAccumulator = 0.0;
bool isCalibrated = false;
bool isHoldingActive = false;

float headingDeg = 0.0;
float targetBearingDeg = 0.0;
float distM = 0.0;

int16_t accelX, accelY, accelZ;
int16_t magX, magY, magZ;

// Для GPS
SoftwareSerial gpsSerial(PIN_GPS_RX, PIN_GPS_TX);
char gpsBuffer[128];
int gpsBufPos = 0;
float gpsLat = 0.0, gpsLon = 0.0;
bool gpsValid = false;

// Отладка
unsigned long debugLastMillis = 0;
const unsigned long debugInterval = 500;

// АВТОКАЛИБРОВКА КОМПАСА
float magMinX = 10000, magMaxX = -10000;
float magMinY = 10000, magMaxY = -10000;
unsigned long compassCalibStart = 0;
bool compassCalibrating = true;
bool compassBiasReady = false;
float compassBiasX = 0.0;
float compassBiasY = 0.0;
const unsigned long COMPASS_CALIB_DURATION = 30000UL; // 30 сек

void setup() {
  Serial.begin(9600);
  Wire.begin();
  gpsSerial.begin(9600);

  escServo.attach(PIN_ESC);
  sendEscPwm(PWM_NEUTRAL);

  pinMode(PIN_STEP, OUTPUT);
  pinMode(PIN_DIR, OUTPUT);
  pinMode(PIN_LIMIT, INPUT_PULLUP);

  pinMode(PIN_HOLD_BTN, INPUT_PULLUP);
  pinMode(PIN_EMER_BTN, INPUT_PULLUP);

  digitalWrite(PIN_STEP, LOW);
  digitalWrite(PIN_DIR, LOW);

  // Инициализация датчиков
  writeReg(ADDR_ADXL345, REG_POWER_CTL, 0x08);
  writeReg(ADDR_ADXL345, REG_DATA_FORMAT, 0x01);

  writeReg(ADDR_HMC5883, REG_CONFIG_A, 0x70);
  writeReg(ADDR_HMC5883, REG_MODE, 0x00);

  Serial.println("System starting...");
  calibrateRudderToHome();

  if (!isCalibrated) {
    Serial.println("ERROR: Rudder calibration failed. Check limit switch.");
  } else {
    Serial.println("Rudder calibration OK.");
  }

  compassCalibStart = millis();
  Serial.println("Starting compass auto-calibration (30s). Rotate boat/device in XY plane.");
}

void loop() {
  handleButtons();

  readAccel();
  readCompass();
  parseGps();

  // Калибровка компаса (первые 30 сек)
  if (compassCalibrating) {
    if (millis() - compassCalibStart >= COMPASS_CALIB_DURATION) {
      compassCalibrating = false;
      compassBiasX = (magMinX + magMaxX) / 2.0;
      compassBiasY = (magMinY + magMaxY) / 2.0;
      compassBiasReady = true;
      Serial.print("Compass calibrated. BiasX="); Serial.print(compassBiasX);
      Serial.print(", BiasY="); Serial.println(compassBiasY);
    } else {
      // Собираем границы магнитного поля
      if (magX < magMinX) magMinX = magX;
      if (magX > magMaxX) magMaxX = magX;
      if (magY < magMinY) magMinY = magY;
      if (magY > magMaxY) magMaxY = magY;
      // Продолжаем сбор данных
    }
  }

  // Установка целевой точки по первому валидному GPS
  if (!targetSet && gpsValid) {
    TARGET_LAT = gpsLat;
    TARGET_LON = gpsLon;
    targetSet = true;
    Serial.print("Target set from GPS: ");
    Serial.print(TARGET_LAT, 6); Serial.print(", "); Serial.println(TARGET_LON, 6);
  }

  if (isHoldingActive && targetSet) {
    if (gpsValid) {
      distM = calculateDistanceMeters(gpsLat, gpsLon, TARGET_LAT, TARGET_LON);
      targetBearingDeg = calculateBearingDeg(gpsLat, gpsLon, TARGET_LAT, TARGET_LON);
      runNavigationLogic(distM, headingDeg, targetBearingDeg, true);
    } else {
      // При потере GPS: держим газ в нейтрали, руль в последнем положении
      sendEscPwm(PWM_NEUTRAL);
      // ВАЖНО: не трогаем руль, чтобы не вызывать резких маневров
    }
  } else if (!isHoldingActive) {
    sendEscPwm(PWM_NEUTRAL);
    // Руль остается в текущем положении (свободное маневрирование)
  }

  if (millis() - debugLastMillis > debugInterval) {
    printDebug();
    debugLastMillis = millis();
  }
}

// --- Обработка кнопок ---
void handleButtons() {
  bool holdPressed = digitalRead(PIN_HOLD_BTN) == LOW;
  bool emerPressed = digitalRead(PIN_EMER_BTN) == LOW;

  static bool lastHoldState = HIGH;
  static unsigned long lastDebounceTime = 0;
  const unsigned long debounceDelay = 50;

  if (holdPressed != lastHoldState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime > debounceDelay) && (holdPressed != lastHoldState)) {
    lastHoldState = holdPressed;
    if (holdPressed) {
      isHoldingActive = !isHoldingActive;
      Serial.print("Hold Mode: ");
      Serial.println(isHoldingActive ? "ON" : "OFF");
      if (isHoldingActive) {
        sendEscPwm(PWM_NEUTRAL);
      }
    }
  }

  if (emerPressed) {
    triggerEmergencyStop();
  }
}

// --- Аварийная остановка ---
void triggerEmergencyStop() {
  Serial.println(">>> EMERGENCY STOP <<<");
  sendEscPwm(PWM_NEUTRAL);
  returnToZero();
  isHoldingActive = false;

  while (digitalRead(PIN_EMER_BTN) == LOW) {
    parseGps();
    delay(10);
  }
  Serial.println("Emergency cleared. System idle.");
}

// --- Возврат руля в 0 (только для аварии) ---
void returnToZero() {
  if (!isCalibrated) return;
  moveRudderTo(0.0);
}

// --- Логика навигации ---
void runNavigationLogic(float dist, float hdg, float target, bool gpsIsAvailable) {
  if (!isCalibrated || !compassBiasReady) return;

  // Если мы в радиусе точки — стоп, руль в 0
  if (dist <= HOLD_RADIUS) {
    sendEscPwm(PWM_NEUTRAL);
    moveRudderTo(0.0);
    return;
  }

  float diff = target - hdg;
  if (diff > 180) diff -= 360;
  if (diff < -180) diff += 360;

  float steerTarget = diff;
  steerTarget = constrain(steerTarget, -MAX_RUDDER_ANGLE, MAX_RUDDER_ANGLE);
  moveRudderTo(steerTarget);

  float power = dist / 50.0;
  power = constrain(power, 0.1, 1.0);

  int pwmValue;
  if (abs(diff) > 90) {
    pwmValue = PWM_REV + (int)((PWM_NEUTRAL - PWM_REV) * power);
  } else {
    pwmValue = PWM_NEUTRAL + (int)((PWM_FWD - PWM_NEUTRAL) * power);
  }
  sendEscPwm(pwmValue);
}

// --- Поворот руля к целевому углу ---
void moveRudderTo(float targetDeg) {
  if (!isCalibrated) return;

  float diff = targetDeg - currentRudderDeg;
  if (diff > 180) diff -= 360;
  if (diff < -180) diff += 360;

  stepAccumulator += diff;
  int stepsToDo = (int)round(fabs(stepAccumulator) / DEG_PER_STEP);

  if (stepsToDo == 0) return;

  digitalWrite(PIN_DIR, (stepAccumulator > 0) ? HIGH : LOW);

  unsigned long stepStart = millis();
  for (int i = 0; i < stepsToDo; i++) {
    if (millis() - stepStart > 5000) break;
    if (digitalRead(PIN_LIMIT) == LOW) {
      currentRudderDeg = 0.0;
      stepAccumulator = 0.0;
      break;
    }
    digitalWrite(PIN_STEP, HIGH);
    delayMicroseconds(STEP_DELAY_US);
    digitalWrite(PIN_STEP, LOW);
    delayMicroseconds(STEP_DELAY_US);
  }

  float movedDeg = stepsToDo * DEG_PER_STEP;
  if (stepAccumulator < 0) movedDeg = -movedDeg;
  stepAccumulator -= movedDeg;

  currentRudderDeg += movedDeg;
  currentRudderDeg = constrain(currentRudderDeg, -MAX_RUDDER_ANGLE, MAX_RUDDER_ANGLE);
}

// --- Отправка PWM на ESC ---
void sendEscPwm(int us) {
  escServo.writeMicroseconds(us);
}

// --- I2C и датчики ---
void writeReg(uint8_t devAddr, uint8_t reg, uint8_t val) {
  Wire.beginTransmission(devAddr);
  Wire.write(reg);
  Wire.write(val);
  Wire.endTransmission(0);
}

void readAccel() {
  Wire.beginTransmission(ADDR_ADXL345);
  Wire.write(REG_DATAX0);
  Wire.endTransmission(0);
  Wire.requestFrom(ADDR_ADXL345, BYTES_TO_READ, STOP_FLAG);

  uint8_t xh = Wire.read();
  uint8_t xl = Wire.read();
  uint8_t yh = Wire.read();
  uint8_t yl = Wire.read();
  uint8_t zh = Wire.read();
  uint8_t zl = Wire.read();

  accelX = (int16_t)(xh << 8 | xl);
  accelY = (int16_t)(yh << 8 | yl);
  accelZ = (int16_t)(zh << 8 | zl);
}

void readCompass() {
  Wire.beginTransmission(ADDR_HMC5883);
  Wire.write(REG_OUT_X_H);
  Wire.endTransmission(0);
  Wire.requestFrom(ADDR_HMC5883, BYTES_TO_READ, STOP_FLAG);

  magX = (int16_t)((Wire.read() << 8) | Wire.read());
  magY = (int16_t)((Wire.read() << 8) | Wire.read());
  magZ = (int16_t)((Wire.read() << 8) | Wire.read());

  // Применяем смещение только после завершения калибровки
  float x = (float)magX;
  float y = (float)magY;
  if (compassBiasReady) {
    x -= compassBiasX;
    y -= compassBiasY;
  }

  float rad = atan2(-y, x);
  headingDeg = rad * 180.0 / PI;
  if (headingDeg < 0) headingDeg += 360.0;
}

// --- Парсинг GPS ---
void parseGps() {
  while (gpsSerial.available()) {
    char c = gpsSerial.read();
    if (c == '\r') continue;
    if (c == '\n') {
      gpsBuffer[gpsBufPos] = '\0';
      processGpsLine(gpsBuffer);
      gpsBufPos = 0;
    } else if (gpsBufPos < 127) {
      gpsBuffer[gpsBufPos++] = c;
    } else {
      gpsBufPos = 0; // защита от переполнения
    }
  }
}

// *** ИСПРАВЛЕНО: Полная реализация функции с проверкой качества ***
void processGpsLine(char *line) {
  // Ищем GPGGA или GNGGA
  if (strncmp(line, "$GPGGA", 6) != 0 && strncmp(line, "$GNGGA", 6) != 0) return;

  char *p = line;
  int field = 0;
  float latDeg = 0.0, lonDeg = 0.0;
  char ns = 'N', ew = 'E';
  int fixQuality = 0;
  int commaCount = 0;

  while (*p) {
    if (*p == ',') {
      commaCount++;
      field++;
    }

    // Поле 6 (индекс 6) — Fix Quality
    if (field == 6 && p[1] != ',' && p[1] != '\0') {
      fixQuality = p[1] - '0';
    }

    // Поле 2 — Широта
    if (field == 2 && commaCount == 2) {
      latDeg = atof(p + 1);
    }
    // Поле 3 — N/S
    if (field == 3 && p[1] != ',' && p[1] != '\0') {
      ns = p[1];
    }
    // Поле 4 — Долгота
    if (field == 4 && commaCount == 4) {
      lonDeg = atof(p + 1);
    }
    // Поле 5 — E/W
    if (field == 5 && p[1] != ',' && p[1] != '\0') {
      ew = p[1];
    }
    p++;
  }

  // Если качество фиксации 0 — данные невалидны
  if (fixQuality == 0) {
    gpsValid = false;
    return;
  }

  // Проверка на адекватность (минимум 14 запятых в GGA)
  if (commaCount < 14) {
    gpsValid = false;
    return;
  }

  float lat = (int)(latDeg / 100) + (latDeg - (int)(latDeg / 100) * 100) / 60.0;
  float lon = (int)(lonDeg / 100) + (lonDeg - (int)(lonDeg / 100) * 100) / 60.0;

  if (ns == 'S') lat = -lat;
  if (ew == 'W') lon = -lon;

  gpsLat = lat;
  gpsLon = lon;
  gpsValid = true;
}

// --- Калибровка руля к HOME ---
void calibrateRudderToHome() {
  isCalibrated = false; currentRudderDeg = 0.0; stepAccumulator = 0.0;
  if (digitalRead(PIN_LIMIT) == LOW) { isCalibrated = true; Serial.println("Already at HOME"); return; }
  Serial.println("Moving to HOME..."); digitalWrite(PIN_DIR, LOW);
  unsigned long start = millis(); const unsigned long MAX_TIME = 8000;
  while (digitalRead(PIN_LIMIT) == HIGH && (millis() - start < MAX_TIME)) {
    digitalWrite(PIN_STEP, HIGH); delayMicroseconds(CALIB_DELAY_US);
    digitalWrite(PIN_STEP, LOW); delayMicroseconds(CALIB_DELAY_US);
  }
  if (digitalRead(PIN_LIMIT) == LOW) { isCalibrated = true; currentRudderDeg = 0.0; stepAccumulator = 0.0; Serial.println("HOME reached."); }
  else { Serial.println("WARNING: HOME not reached."); isCalibrated = false; }
}

// --- Математика GPS ---
float calculateDistanceMeters(float lat1, float lon1, float lat2, float lon2) {
  const float R = 6371000.0;
  float phi1 = lat1 * PI / 180.0, phi2 = lat2 * PI / 180.0;
  float dPhi = (lat2 - lat1) * PI / 180.0, dLambda = (lon2 - lon1) * PI / 180.0;
  float a = sin(dPhi / 2.0) * sin(dPhi / 2.0) + cos(phi1) * cos(phi2) * sin(dLambda / 2.0) * sin(dLambda / 2.0);
  float c = 2.0 * atan2(sqrt(a), sqrt(1.0 - a)); return R * c;
}

float calculateBearingDeg(float lat1, float lon1, float lat2, float lon2) {
  float phi1 = lat1 * PI / 180.0, phi2 = lat2 * PI / 180.0, dLambda = (lon2 - lon1) * PI / 180.0;
  float y = sin(dLambda) * cos(phi2);
  float x = cos(phi1) * sin(phi2) - sin(phi1) * cos(phi2) * cos(dLambda);
  float brng = atan2(y, x) * 180.0 / PI; if (brng < 0) brng += 360.0; return brng;
}

// --- Отладка ---
void printDebug() {
  Serial.print("Dist: "); Serial.print(distM); Serial.print("m | ");
  Serial.print("Bearing: "); Serial.print(targetBearingDeg); Serial.print(" | ");
  Serial.print("Heading: "); Serial.print(headingDeg); Serial.print(" | ");
  Serial.print("Rudder: "); Serial.print(currentRudderDeg); Serial.print(" | ");
  Serial.print("GPS: "); Serial.println(gpsValid ? "OK" : "LOST");
}
